const React=require('react'),{createRoot}=require('react-dom/client');
const {DashboardLoadingProgress}=require('../../components/dashboard/dashboard-loading-progress.tsx');
const {beginForegroundLoading}=require('../../lib/display/foreground-loading.ts');
const {TenhBotWorkspace}=require('../../components/bot/tenh-bot-workspace.tsx');
const b='00000000-0000-4000-8000-000000000001',c='00000000-0000-4000-8000-000000000002',c2='00000000-0000-4000-8000-000000000003';
const tables=new Map(),requests=[];
window.history.replaceState(null,'','?bot=welcome_away');window.fetch=async(url,init={})=>{if(url==='/api/facebook/auto-reply')return Response.json({rules:[],pages:[],history:[],canManage:true,paused:true,workerEnabled:false});requests.push({url,method:init.method??'GET'});if(url.includes('scope=drafts'))return Response.json({businessId:b,canManage:true,pages:[{id:c,platform:'facebook',account_name:'Fixture Page',platform_account_id:'123'},{id:c2,platform:'facebook',account_name:'Other Page',platform_account_id:'456'}],members:[]});if(init.method==='POST'){const body=JSON.parse(init.body),old=tables.get(body.channelId);if(body.revision!==(old?.revision??0))return Response.json({error:'Revision conflict'},{status:409});tables.set(body.channelId,{rules:body.rules,revision:(old?.revision??0)+1});return Response.json({success:true,revision:(old?.revision??0)+1,enabled:false});}const channel=new URL(url,location.origin).searchParams.get('channelId');return Response.json(tables.get(channel)??{rules:[],revision:0});};
createRoot(document.getElementById('root')).render(React.createElement(React.Fragment,null,React.createElement('header',{id:'header',style:{position:'relative',height:72,width:800}},React.createElement(DashboardLoadingProgress)),React.createElement('div',{id:'content'},React.createElement(TenhBotWorkspace))));
const pause=ms=>new Promise(r=>setTimeout(r,ms)),checks=[],check=(name,value)=>{if(!value)throw Error(name);checks.push(name)};
const button=text=>[...document.querySelectorAll('button')].find(x=>x.textContent===text);
function setInput(node,value){Object.getOwnPropertyDescriptor(node.tagName==='SELECT'?HTMLSelectElement.prototype:node.tagName==='TEXTAREA'?HTMLTextAreaElement.prototype:HTMLInputElement.prototype,'value').set.call(node,value);node.dispatchEvent(new Event(node.tagName==='SELECT'?'change':'input',{bubbles:true}));}
(async()=>{try{await pause(120);check('thirteen separate menu choices',document.querySelectorAll('nav[aria-label="Bots"] button').length===13);check('deep link selects welcome',document.querySelector('[aria-current="page"]').textContent.includes('Welcome'));const input=label=>[...document.querySelectorAll('label')].find(x=>x.textContent.startsWith(label)&&x.offsetParent!==null).querySelector('input,textarea');const choose=label=>[...document.querySelectorAll('nav button')].find(x=>x.textContent===label);setInput(input('Name'),'Unfinished welcome');await pause(30);choose('Keyword FAQ').click();await pause(30);check('new kind gets own fields',input('Name').value==='');setInput(input('Name'),'FAQ draft');await pause(30);choose('Welcome / Away').click();await pause(30);check('unfinished welcome retained',input('Name').value==='Unfinished welcome');const channel=document.querySelector('select');setInput(channel,c);await pause(80);setInput(input('Reply / welcome template'),'Hello');setInput(input('Away template'),'Away');await pause(30);button('Add session draft').click();await pause(30);check('selected rule visible',document.querySelector('section ul').textContent.includes('Unfinished welcome'));choose('Keyword FAQ').click();await pause(30);check('other Bot rules hidden',!document.querySelector('section ul').textContent.includes('Unfinished welcome'));check('unfinished FAQ retained',input('Name').value==='FAQ draft');button('Save disabled rules').click();await pause(80);check('save preserves other Bot rules',tables.get(c)?.rules.length===1&&tables.get(c).rules[0].kind==='welcome_away');choose('Facebook Comment Auto Reply').click();await pause(80);check('legacy distinct without duplicate editor',document.querySelectorAll('section').length>0&&document.querySelector('[aria-current="page"]').textContent==='Facebook Comment Auto Reply');choose('Welcome / Away').click();await pause(30);check('editor state survives legacy visit',input('Name').value==='Unfinished welcome');check('menu buttons keyboard focusable',[...document.querySelectorAll('nav button')].every(x=>x.tabIndex===0));check('no provider sends',requests.every(x=>x.url.startsWith('/api/tenh-bot/rules')||x.url==='/api/facebook/auto-reply?scope=drafts'));document.getElementById('result').textContent=JSON.stringify({passed:true,checks});}catch(error){document.getElementById('result').textContent=JSON.stringify({passed:false,error:error.message,checks});}})();